<?php
if (isset($_SERVER['SCRIPT_FILENAME']) && realpath($_SERVER['SCRIPT_FILENAME']) === __FILE__) { http_response_code(404); exit; }   // include-only: never executable directly
/**
 * Advertising performance, revenue dashboard and sales-opportunity report (Phase 7F). RECORDED data only: clicks come from the existing click analytics (adm_tool_daily), money from the
 * existing contract and revenue entries. Impressions are NOT measured by the site, so they (and therefore click-through rate) are reported as unavailable, never estimated. Money stays per
 * currency. null = unavailable (storage missing); an empty list or 0 = recorded as nothing; the caller says which.
 */
require_once __DIR__ . '/ad_core.php';

/** @return array<string,mixed> Measured figures for one booking's window. impressions and ctr are always null (not measured). */
function ad_campaign_metrics(PDO $pdo, array $b, ?int $nowTs = null): array {
  $today = ad_today($nowTs); $s = $b['start_date']; $e = $b['end_date']; $m = ['start' => $s, 'end' => $e, 'days_total' => null, 'days_elapsed' => null, 'days_remaining' => null, 'phase' => 'no_dates', 'analytics' => null, 'tool_views' => null, 'outbound' => null, 'sponsored' => null, 'scope' => $b['tool_slug'] !== '' ? 'tool' : ($b['category'] !== '' ? 'category' : 'none'), 'impressions' => null, 'ctr' => null, 'impressions_note' => 'The site does not measure placement impressions, so impressions and click-through rate are not available and are never estimated.'];
  if ($s && $e) { $d = fn($x) => (int)round((strtotime($x . ' UTC') - strtotime($s . ' UTC')) / 86400); $m['days_total'] = $d($e) + 1; $m['phase'] = $today < $s ? 'not_started' : ($today > $e ? 'ended' : 'running'); $m['days_elapsed'] = $today < $s ? 0 : min($m['days_total'], $d($today) + 1); $m['days_remaining'] = $today > $e ? 0 : max(0, (int)round((strtotime($e . ' UTC') - strtotime(max($today, $s) . ' UTC')) / 86400) + ($today < $s ? 1 : 0)); }
  try { $pdo->query('SELECT 1 FROM adm_tool_daily LIMIT 1'); } catch (Throwable $x) { $m['analytics'] = false; return $m; } $m['analytics'] = true; if (!$s || !$e || $today < $s) { $m['tool_views'] = $m['outbound'] = $m['sponsored'] = $m['phase'] === 'not_started' ? 0 : null; return $m; }
  $to = min($e, $today); $slugs = []; if ($b['tool_slug'] !== '') $slugs = [$b['tool_slug']]; elseif ($b['category'] !== '') foreach (ad_catalogue() as $id => $t) if (strcasecmp((string)($t['category'] ?? ''), $b['category']) === 0) $slugs[] = (string)$id;
  if (!$slugs) { $m['tool_views'] = $m['outbound'] = $m['sponsored'] = null; return $m; } $in = implode(',', array_fill(0, count($slugs), '?')); $q = $pdo->prepare("SELECT COALESCE(SUM(tool_views),0) v, COALESCE(SUM(outbound_clicks),0) o, COALESCE(SUM(sponsored_clicks),0) sp FROM adm_tool_daily WHERE day BETWEEN ? AND ? AND tool_slug IN ($in)"); $q->execute(array_merge([$s, $to], $slugs)); $r = $q->fetch(PDO::FETCH_ASSOC);
  $m['tool_views'] = (int)$r['v']; $m['outbound'] = (int)$r['o']; $m['sponsored'] = (int)$r['sp']; return $m;
}
function ad_report_row(PDO $pdo, array $b, ?int $nowTs = null): array { $m = ad_campaign_metrics($pdo, $b, $nowTs); $p = ad_payment_summary($pdo, $b); return ['booking' => $b, 'metrics' => $m, 'payment' => $p]; }
function ad_csv_cell($v): string { $s = (string)$v; return $s !== '' && strpos("=+-@\t\r", $s[0]) !== false ? "'" . $s : $s; }
function ad_report_csv(PDO $pdo, ?int $nowTs = null): string {
  $f = fopen('php://temp', 'w+'); fwrite($f, "\xEF\xBB\xBF"); fputcsv($f, ['booking', 'advertiser', 'package', 'tool', 'category', 'status', 'start', 'end', 'days_total', 'days_remaining', 'outbound_clicks', 'sponsored_clicks', 'tool_page_views', 'impressions', 'click_through_rate', 'currency', 'agreed', 'invoiced', 'received', 'outstanding', 'refunds', 'payment_state'], ',', '"', '\\');
  foreach (ad_bookings_list($pdo, [], 500) as $b) { $r = ad_report_row($pdo, $b, $nowTs); $m = $r['metrics']; $p = $r['payment']; $mn = fn($x) => $x === null ? '' : ad_minor((int)$x);
    fputcsv($f, array_map('ad_csv_cell', [$b['id'], $b['company_name'], $b['package_name'], $b['tool_slug'], $b['category'], $b['status'], $b['start_date'], $b['end_date'], $m['days_total'], $m['days_remaining'], $m['outbound'] ?? 'unavailable', $m['sponsored'] ?? 'unavailable', $m['tool_views'] ?? 'unavailable', 'not measured', 'not available', $p['currency'], $mn($p['agreed']), $mn($p['invoiced']), $mn($p['received']), $mn($p['outstanding']), $mn($p['refunds']), ad_payment_state_label($p['state'])]), ',', '"', '\\'); }
  rewind($f); $o = (string)stream_get_contents($f); fclose($f); return $o;
}
function ad_report_print_html(PDO $pdo, int $id, ?int $nowTs = null): ?string {
  $b = ad_booking_get($pdo, $id); if (!$b) return null; $r = ad_report_row($pdo, $b, $nowTs); $m = $r['metrics']; $p = $r['payment']; $h = fn($s) => htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); $n = fn($v) => $v === null ? 'Unavailable' : number_format((int)$v); $mon = fn($v, $c) => $v === null ? '-' : $h(crm_money_format((int)$v, (string)$c));
  $name = function_exists('site_cfg') ? (getenv('AIHUB_BUSINESS_NAME') ?: 'TrustNova Tech') : 'TrustNova Tech';
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Campaign report #' . (int)$id . '</title><style>body{margin:0;background:#f4f2fb;color:#1c1740;font:14px/1.5 "Helvetica Neue",Arial,sans-serif}.bar{max-width:820px;margin:16px auto 0;padding:0 16px;display:flex;gap:10px;flex-wrap:wrap;justify-content:space-between}.bar a,.bar button{min-height:44px;padding:0 16px;border-radius:10px;border:1px solid #4f2fd6;background:#4f2fd6;color:#fff;font:inherit;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center}.bar a.sec{background:#fff;color:#4f2fd6}.page{max-width:820px;margin:12px auto 32px;background:#fff;padding:36px 40px;border:1px solid #e3def3;border-radius:12px}h1{margin:0 0 4px;font-size:24px}h2{font-size:15px;margin:22px 0 6px}table{width:100%;border-collapse:collapse}th,td{padding:7px 6px;border-bottom:1px solid #e3def3;text-align:left;vertical-align:top}th{width:46%;font-weight:600;color:#5f5a7a}.small{font-size:12px;color:#5f5a7a}.tw{overflow-x:auto}@media print{body{background:#fff}.bar{display:none}.page{border:0;margin:0;padding:0;max-width:none}@page{size:A4;margin:16mm}}@media (max-width:600px){.page{padding:18px 14px}}</style></head><body>'
    . '<div class="bar"><a class="sec" href="/admin-center.php?m=advertising&amp;view=booking&amp;id=' . (int)$id . '">Back to the booking</a><button type="button" onclick="window.print()">Print or save as PDF</button></div><div class="page"><div class="small">' . $h($name) . ' - advertising campaign report</div><h1>' . $h($b['company_name']) . ': ' . $h($b['package_name'] ?: 'Campaign') . '</h1><div class="small">Generated ' . $h(gmdate('Y-m-d', $nowTs ?? time())) . ' (UTC). Only recorded figures are shown; nothing is estimated.</div>'
    . '<h2>Campaign</h2><div class="tw"><table><tbody><tr><th scope="row">Status</th><td>' . $h(ad_statuses()[$b['status']] ?? $b['status']) . '</td></tr><tr><th scope="row">Placement</th><td>' . $h($b['tool_slug'] ?: ($b['category'] ? 'Category: ' . $b['category'] : '-')) . ' (labelled ' . $h($b['disclosure_label'] ?: 'Sponsored') . ')</td></tr><tr><th scope="row">Dates</th><td>' . $h(($b['start_date'] ?: '-') . ' to ' . ($b['end_date'] ?: '-')) . '</td></tr><tr><th scope="row">Duration / remaining</th><td>' . ($m['days_total'] === null ? 'Dates not set' : (int)$m['days_total'] . ' days / ' . (int)$m['days_remaining'] . ' days remaining') . '</td></tr></tbody></table></div>'
    . '<h2>Measured performance</h2><div class="tw"><table><tbody><tr><th scope="row">Outbound clicks to the advertiser during the campaign' . ($m['scope'] === 'category' ? ' (all tools in the category)' : '') . '</th><td>' . $n($m['outbound']) . '</td></tr><tr><th scope="row">of which from sponsored placements</th><td>' . $n($m['sponsored']) . '</td></tr><tr><th scope="row">Tool page views</th><td>' . $n($m['tool_views']) . '</td></tr><tr><th scope="row">Impressions</th><td>Not measured</td></tr><tr><th scope="row">Click-through rate</th><td>Not available (needs impressions)</td></tr></tbody></table></div><p class="small">' . $h($m['impressions_note']) . ' Counts come from the site\'s own cookie-free analytics and are a floor: visitors who block tracking or send Do-Not-Track or Global Privacy Control are not counted. Clicks are not conversions or sales.</p>'
    . '<h2>Payment</h2><div class="tw"><table><tbody><tr><th scope="row">Agreed price</th><td>' . $mon($p['agreed'], $p['currency']) . '</td></tr><tr><th scope="row">Invoiced / received</th><td>' . $mon($p['invoiced'], $p['currency']) . ' / ' . $mon($p['received'], $p['currency']) . '</td></tr><tr><th scope="row">Outstanding</th><td>' . $mon($p['outstanding'], $p['currency']) . '</td></tr><tr><th scope="row">Status</th><td>' . $h(ad_payment_state_label($p['state'])) . '</td></tr></tbody></table></div></div></body></html>';
}

// ---- dashboard ------------------------------------------------------------------------------------------------------------------------------------
function ad_dashboard(PDO $pdo, ?int $nowTs = null): array {
  $today = ad_today($nowTs); $d = ['ready' => ad_ready($pdo), 'today' => $today]; if (!$d['ready']) return $d + ['bookings' => null, 'advertisers' => null, 'campaigns' => null, 'available' => null, 'enquiries' => null, 'money' => [], 'by_package' => [], 'by_advertiser' => [], 'trend' => [], 'renewals' => [], 'expiring' => [], 'inventory' => [], 'by_status' => []];
  $by = array_fill_keys(array_keys(ad_statuses()), 0); foreach ($pdo->query('SELECT status, COUNT(*) n FROM ad_booking GROUP BY status')->fetchAll(PDO::FETCH_KEY_PAIR) as $k => $n) $by[$k] = (int)$n; $total = array_sum($by);
  $adv = (int)$pdo->query("SELECT COUNT(DISTINCT company_id) FROM ad_booking WHERE status IN ('active','paused')")->fetchColumn(); $enq = (int)$pdo->query("SELECT COUNT(*) FROM crm_campaigns g LEFT JOIN ad_booking b ON b.campaign_id = g.id WHERE g.is_synthetic = 0 AND g.status IN ('inquiry','in_review') AND (b.id IS NULL OR b.status IN ('draft','enquiry_received'))")->fetchColumn();
  $inv = ad_inventory($pdo, $nowTs); $avail = 0; $anyAvail = false; foreach ($inv as $i) if ($i['available'] && $i['scope'] === 'global' && $i['free_now'] !== null) { $anyAvail = true; $avail += $i['free_now']; }
  $money = []; $pkg = []; $advs = []; $trend = []; $months = []; $ym = gmdate('Y-m', strtotime($today . ' UTC')); for ($i = 11; $i >= 0; $i--) $months[] = gmdate('Y-m', strtotime($ym . '-01 UTC -' . $i . ' months'));
  $bks = ad_bookings_list($pdo, [], 500); foreach ($bks as $b) {
    $p = ad_payment_summary($pdo, $b); $c = $p['currency'] ?: ($b['currency'] ?: null); if ($c === null) continue; $money[$c] = $money[$c] ?? ['agreed_open' => 0, 'invoiced' => 0, 'outstanding' => 0, 'received' => 0, 'refunds' => 0, 'net_received' => 0];
    $held = in_array($b['status'], AD_HOLDS, true) || ($b['status'] === 'proposal_sent' && $p['has_contract']); if ($held && $p['agreed'] !== null) $money[$c]['agreed_open'] += max(0, $p['agreed'] - $p['received']);
    foreach (['invoiced', 'outstanding', 'received', 'refunds', 'net_received'] as $k) $money[$c][$k] += $p[$k];
    $pk = $b['package_name'] ?: '(no package)'; $pkg[$pk][$c] = $pkg[$pk][$c] ?? ['net' => 0, 'agreed' => 0, 'n' => 0]; $pkg[$pk][$c]['net'] += $p['net_received']; $pkg[$pk][$c]['agreed'] += (int)($p['agreed'] ?? 0); $pkg[$pk][$c]['n']++;
    $ak = $b['company_name'] ?: ('#' . $b['company_id']); $advs[$ak][$c] = $advs[$ak][$c] ?? ['net' => 0, 'agreed' => 0, 'n' => 0]; $advs[$ak][$c]['net'] += $p['net_received']; $advs[$ak][$c]['agreed'] += (int)($p['agreed'] ?? 0); $advs[$ak][$c]['n']++;
  }
  ksort($money); $rv = $pdo->query("SELECT DATE_FORMAT(r.entry_date, '%Y-%m') m, r.currency, SUM(r.amount_minor) s FROM crm_revenue_entries r JOIN ad_booking b ON b.contract_id = r.contract_id WHERE r.kind = 'received' AND r.is_synthetic = 0 GROUP BY m, r.currency")->fetchAll(PDO::FETCH_ASSOC); foreach ($rv as $r) if (in_array($r['m'], $months, true)) $trend[$r['currency']][$r['m']] = (int)$r['s']; ksort($trend);
  $ren = $pdo->prepare("SELECT b.id, b.company_id, c.name company, COALESCE(b.renewal_date, b.end_date) due, b.status, p.name package FROM ad_booking b LEFT JOIN crm_companies c ON c.id = b.company_id LEFT JOIN ad_package p ON p.id = b.package_id WHERE b.status IN ('scheduled','active','paused') AND COALESCE(b.renewal_date, b.end_date) BETWEEN ? AND ? ORDER BY due"); $ren->execute([$today, gmdate('Y-m-d', strtotime($today . ' UTC') + 45 * 86400)]);
  $exp = $pdo->prepare("SELECT b.id, c.name company, b.end_date, b.status, p.name package FROM ad_booking b LEFT JOIN crm_companies c ON c.id = b.company_id LEFT JOIN ad_package p ON p.id = b.package_id WHERE b.status IN ('scheduled','active','paused') AND b.end_date BETWEEN ? AND ? ORDER BY b.end_date"); $exp->execute([$today, gmdate('Y-m-d', strtotime($today . ' UTC') + 14 * 86400)]);
  return $d + ['bookings' => $total, 'advertisers' => $adv, 'campaigns' => $by['active'], 'available' => $anyAvail ? $avail : null, 'enquiries' => $enq, 'money' => $money, 'by_package' => $pkg, 'by_advertiser' => $advs, 'trend' => $trend, 'months' => $months, 'renewals' => $ren->fetchAll(PDO::FETCH_ASSOC), 'expiring' => $exp->fetchAll(PDO::FETCH_ASSOC), 'inventory' => $inv, 'by_status' => $by];
}

// ---- sales opportunities ----------------------------------------------------------------------------------------------------------------------------
function ad_opportunities(PDO $pdo, ?int $nowTs = null): array {
  $today = ad_today($nowTs); $from = gmdate('Y-m-d', strtotime($today . ' UTC') - 89 * 86400); $o = ['ready' => ad_ready($pdo), 'from' => $from, 'to' => $today]; if (!$o['ready']) return $o + ['analytics' => null, 'tools' => [], 'categories' => [], 'inventory' => [], 'renewals' => [], 'partners' => [], 'enquiries' => []];
  $cat = ad_catalogue(); $analytics = true; try { $pdo->query('SELECT 1 FROM adm_tool_daily LIMIT 1'); } catch (Throwable $e) { $analytics = false; } $clicks = [];
  if ($analytics) { $q = $pdo->prepare('SELECT tool_slug, SUM(outbound_clicks) o FROM adm_tool_daily WHERE day BETWEEN ? AND ? GROUP BY tool_slug'); $q->execute([$from, $today]); $clicks = $q->fetchAll(PDO::FETCH_KEY_PAIR); }
  $held = []; foreach ($pdo->query("SELECT tool_slug, category FROM ad_booking WHERE status IN ('awaiting_payment','scheduled','active','paused')")->fetchAll(PDO::FETCH_ASSOC) as $r) { if ($r['tool_slug'] !== '') $held['t'][$r['tool_slug']] = 1; if ($r['category'] !== '') $held['c'][mb_strtolower($r['category'])] = 1; }
  $tools = []; foreach ($clicks as $slug => $n) if ((int)$n > 0 && isset($cat[$slug])) $tools[] = ['slug' => $slug, 'name' => (string)$cat[$slug]['name'], 'category' => (string)($cat[$slug]['category'] ?? ''), 'outbound' => (int)$n, 'booked' => isset($held['t'][$slug])]; usort($tools, fn($a, $b) => $b['outbound'] <=> $a['outbound']);
  $cats = []; foreach ($clicks as $slug => $n) if (isset($cat[$slug])) { $k = (string)($cat[$slug]['category'] ?? '') ?: '(no category)'; $cats[$k] = $cats[$k] ?? ['category' => $k, 'outbound' => 0, 'tools' => 0, 'sponsored' => isset($held['c'][mb_strtolower($k)])]; $cats[$k]['outbound'] += (int)$n; $cats[$k]['tools']++; } usort($cats, fn($a, $b) => $b['outbound'] <=> $a['outbound']);
  $rn = $pdo->prepare("SELECT b.company_id, c.name company, MAX(b.end_date) last_end, COUNT(*) n, SUM(CASE WHEN b.status IN ('scheduled','active','paused','awaiting_payment','proposal_sent','enquiry_received') AND b.end_date > ? THEN 1 ELSE 0 END) open_later FROM ad_booking b LEFT JOIN crm_companies c ON c.id = b.company_id WHERE b.status IN ('active','paused','completed','expired') AND b.end_date >= ? AND b.end_date <= ? GROUP BY b.company_id, c.name ORDER BY last_end"); $rn->execute([gmdate('Y-m-d', strtotime($today . ' UTC') + 30 * 86400), gmdate('Y-m-d', strtotime($today . ' UTC') - 60 * 86400), gmdate('Y-m-d', strtotime($today . ' UTC') + 30 * 86400)]); $ren = array_values(array_filter($rn->fetchAll(PDO::FETCH_ASSOC), fn($r) => (int)$r['open_later'] === 0));
  $pr = $pdo->query("SELECT p.id, p.company_name, p.website, p.fit_status, p.kind FROM crm_prospects p WHERE p.is_synthetic = 0 AND p.kind = 'advertising' AND p.fit_status IN ('unqualified','fit') ORDER BY p.id DESC LIMIT 30")->fetchAll(PDO::FETCH_ASSOC); $adNames = array_map('mb_strtolower', $pdo->query("SELECT c.name FROM ad_booking b JOIN crm_companies c ON c.id = b.company_id")->fetchAll(PDO::FETCH_COLUMN)); $pr = array_values(array_filter($pr, fn($x) => !in_array(mb_strtolower($x['company_name']), $adNames, true)));
  $en = $pdo->query("SELECT l.id, l.created_at, l.status, c.id company_id, c.name company, (SELECT COUNT(*) FROM ad_booking b WHERE b.company_id = c.id) bookings FROM crm_leads l JOIN crm_companies c ON c.id = l.company_id WHERE l.is_synthetic = 0 AND l.kind = 'advertising' AND l.status IN ('new','qualified') ORDER BY l.id DESC LIMIT 30")->fetchAll(PDO::FETCH_ASSOC);
  return $o + ['analytics' => $analytics, 'tools' => array_slice($tools, 0, 15), 'categories' => array_slice($cats, 0, 12), 'inventory' => ad_inventory($pdo, $nowTs), 'renewals' => $ren, 'partners' => $pr, 'enquiries' => $en];
}
/** A draft to a researched prospect. Blocked when the prospect is marked not a fit or archived, or when its company (matched by website domain) has a contact who unsubscribed. Never sent: drafts are text for a person to review. */
function ad_outreach_draft(PDO $pdo, ?array $user, int $prospectId, string $subject, string $body): array {
  if (ad_deny($user, 'outreach')) return [false, 'forbidden']; $s = $pdo->prepare('SELECT * FROM crm_prospects WHERE id = ?'); $s->execute([$prospectId]); $p = $s->fetch(PDO::FETCH_ASSOC); if (!$p) return [false, 'prospect_not_found']; if (in_array($p['fit_status'], ['not_fit', 'archived'], true)) return [false, 'prospect_suppressed'];
  if ($p['domain'] !== '') { $u = $pdo->prepare("SELECT 1 FROM crm_contacts k JOIN crm_companies c ON c.id = k.company_id WHERE c.domain = ? AND (k.unsubscribed_at IS NOT NULL OR k.consent_status = 'unsubscribed') LIMIT 1"); $u->execute([$p['domain']]); if ($u->fetchColumn()) return [false, 'prospect_suppressed']; }
  return crm_outreach_draft_add($pdo, $user, $subject, $body, $prospectId, null);
}
